final readonly class Money
{
    private function __construct(
        public int $amount,        // minor unit: cents
        public string $currency,   // 'USD'
    ) {}

    public static function of(int $minor, string $currency): self
    {
        return new self($minor, strtoupper($currency));
    }

    public function add(self $other): self
    {
        $this->assertSameCurrency($other);
        $sum = $this->amount + $other->amount;
        if (!is_int($sum)) {            // on overflow PHP turns it into a float
            throw new \OverflowException('Money overflow');
        }

        return new self($sum, $this->currency);
    }

    private function assertSameCurrency(self $other): void
    {
        if ($this->currency !== $other->currency) {
            throw new \DomainException("Cannot add {$this->currency} to {$other->currency}");
        }
    }
}

#[ORM\Entity]
class Wallet
{
    #[ORM\Id, ORM\GeneratedValue, ORM\Column]
    private ?int $id = null;

    #[ORM\Column(type: Types::BIGINT)]
    private int $balanceMinor = 0;      // in cents, never a float

    #[ORM\Column(length: 3)]
    private string $currency = 'USD';

    public function balance(): Money
    {
        return Money::of($this->balanceMinor, $this->currency);
    }
}

/** @return list<self> */
public function allocate(int ...$ratios): array
{
    if ($this->amount < 0 || array_sum($ratios) <= 0) {
        throw new \DomainException('allocate: invalid amount or ratios');
    }

    $total = array_sum($ratios);
    $shares = array_map(fn (int $r) => intdiv($this->amount * $r, $total), $ratios);
    $remainder = $this->amount - array_sum($shares);

    for ($i = 0; $remainder > 0; $i++, $remainder--) {
        $shares[$i]++;                      // hand out the remainder one cent at a time
    }

    return array_map(fn (int $s) => new self($s, $this->currency), $shares);
}

