/** @param list<Posting> $postings */
public function post(string $memo, array $postings, ?Uuid $reverses = null): Uuid
{
    $net = [];                                    // currency => debits minus credits
    foreach ($postings as $p) {
        $signed = Side::Debit === $p->side ? $p->money->amount : -$p->money->amount;
        $net[$p->money->currency] = ($net[$p->money->currency] ?? 0) + $signed;
    }
    if ([] === $net || [] !== array_filter($net)) {
        throw new \DomainException('Debits and credits must be equal in every currency');
    }

    return $this->db->transactional(function () use ($memo, $postings, $reverses) {
        $id = Uuid::v7();
        $this->db->insert('ledger_transaction', [
            'id' => $id->toRfc4122(), 'memo' => $memo,
            'reverses_id' => $reverses?->toRfc4122(),
        ]);
        foreach ($postings as $p) {
            $this->db->insert('ledger_entry', [
                'transaction_id' => $id->toRfc4122(),
                'account_id' => $p->accountId,
                'side' => $p->side->value,
                'amount_minor' => $p->money->amount,
                'currency' => $p->money->currency,
            ]);
        }

        return $id;
    });
}

public function reverse(Uuid $txId): Uuid
{
    $original = $this->entries->forTransaction($txId);   // list<Posting>

    return $this->post(
        memo: "Reversal of {$txId->toRfc4122()}",
        postings: array_map(fn (Posting $p) => $p->reversed(), $original),
        reverses: $txId,
    );
}

