final class ReconcileCommand extends Command
{
    public function __construct(private readonly Reconciler $reconciler)
    {
        parent::__construct();
    }

    protected function configure(): void
    {
        $this->addArgument('date', InputArgument::OPTIONAL, 'Which day', '2 days ago');
    }

    protected function execute(InputInterface $in, OutputInterface $out): int
    {
        $day = new \DateTimeImmutable($in->getArgument('date'));
        $breaks = $this->reconciler->run($day);   // fetches the statement, runs the query
        $out->writeln(sprintf('%s: %d breaks', $day->format('Y-m-d'), $breaks));

        return Command::SUCCESS;
    }
}

