interface PaymentGateway
{
    /** @throws GatewayUnavailable|GatewayDeclined */
    public function charge(ChargeRequest $request): ChargeResult;
}

final readonly class AcmePayGateway implements PaymentGateway
{
    public function __construct(private AcmeClient $client) {}

    public function charge(ChargeRequest $r): ChargeResult
    {
        $raw = $this->client->charge($r->key, $r->money->amount);

        return new ChargeResult(
            vendorRef: $raw['id'],
            status: 'paid' === $raw['state'] ? ChargeStatus::Paid : ChargeStatus::Pending,
        );
    }
}

public function import(string $provider, string $path, string $expectedSha): void
{
    $hash = hash_file('sha256', $path);
    if (!hash_equals($expectedSha, $hash)) {
        throw new CorruptedFile($path);          // damaged on the way
    }
    if (null === $fileId = $this->files->claim($provider, basename($path), $hash)) {
        return;                                  // already loaded (or rejected): skip
    }

    $file = $this->parser->parse($path);         // header, rows, trailer
    $sum = array_sum(array_map(fn (Row $r) => $r->amountMinor, $file->rows));
    if (count($file->rows) !== $file->count || $sum !== $file->totalMinor) {
        $this->files->reject($fileId, 'control total mismatch');
        return;                                  // not one row was loaded
    }

    foreach ($file->rows as $line => $row) {
        try {
            $this->loader->load($fileId, $line, $row);
        } catch (InvalidRow $e) {
            $this->files->quarantine($fileId, $line, $row->raw, $e->getMessage());
        }
    }
    $this->files->markLoaded($fileId);
}

