public function load(int $fileId, int $line, Row $row): void
{
    $this->em->wrapInTransaction(function () use ($fileId, $line, $row): void {
        $ticked = $this->em->getConnection()->executeStatement(
            'INSERT INTO batch_row (file_id, line_no) VALUES (?, ?)
             ON CONFLICT DO NOTHING',
            [$fileId, $line],
        );
        if (0 === $ticked) {
            return;                         // credited before the crash: skip
        }
        $this->wallet->credit($row->userId, $row->amountMinor);   // same transaction
    });
}

